function Encrypt-Backup {
    param([string]$BackupFolder, [string]$Password)

    # Use Windows DPAPI for encryption
    $backupZip = "$BackupFolder.zip"
    Compress-Archive -Path "$BackupFolder\*" -DestinationPath $backupZip -Force

    # Encrypt with password (using 7-Zip if available, otherwise use AES)
    if (Test-Path "7z.exe") {
        & 7z.exe a -p$Password -mhe=on $backupZip.encrypted $backupZip
        Remove-Item $backupZip -Force
        return "$backupZip.encrypted"
    } else {
        # Fallback: encrypt manifest only
        $manifestPath = Join-Path $BackupFolder "BACKUP_MANIFEST.json"
        $encryptedManifest = ConvertTo-SecureString -String (Get-Content $manifestPath -Raw) -AsPlainText -Force
        $encryptedManifest | ConvertFrom-SecureString | Set-Content "$manifestPath.enc"
        Remove-Item $manifestPath -Force
        return $backupZip
    }
}
